"""Company sales offer screen; all calculations and persistence use the server."""
HTML = '''<div data-view="propuestas-ventas" hidden>
<section class="card"><h2>PROPUESTAS DE VENTA</h2><p>Prepara una oferta para un cliente con varias líneas. Los precios y las existencias son referencias de la versión documental activa.</p>
<form id="sales-offer-form"><div class="fields"><label>Cliente<select id="so-customer" required></select></label><label>Referencia de la oferta<input id="so-reference" maxlength="100" required></label><label>Fecha de la oferta<input id="so-date" placeholder="DD/MM/AAAA" required></label><label>Válida hasta<input id="so-valid" placeholder="DD/MM/AAAA" required></label></div>
<div id="so-lines"></div><button id="so-add" type="button">+ Añadir artículo</button>
<div class="fields"><label>Entrega prevista<input id="so-delivery-date" placeholder="DD/MM/AAAA" required></label><label>Lugar de entrega<input id="so-delivery" maxlength="500" required></label><label>Cobro previsto<input id="so-due" placeholder="DD/MM/AAAA" required></label><label>Condiciones de cobro<input id="so-payment" maxlength="500" required></label><label>Portes facturados al cliente, sin IVA (€)<input id="so-freight" inputmode="decimal" value="0" required></label><label>IVA de los portes (%)<input id="so-freight-vat" inputmode="decimal" required></label></div>
<p>Importes en EUR. Introduce expresamente el IVA aplicable; EIOS no lo deduce del cliente o del artículo. Usa números como 1.234,50.</p>
<div class="files-actions"><button id="so-preview" type="button">Calcular oferta</button><button class="primary" id="so-save" type="submit">Guardar propuesta de venta</button></div><p id="so-notice" role="status"></p><div id="so-summary"></div></form></section>
<section class="card"><h2>OFERTAS GUARDADAS</h2><p>Consulta e imprime la versión guardada para el cliente. El documento excluye costes y márgenes internos.</p><div class="scroll"><table><thead><tr><th>Referencia / fecha</th><th>Cliente</th><th>Total</th><th>Vigencia</th><th>Documento</th></tr></thead><tbody id="so-saved"></tbody></table></div></section></div>'''
CSS = '''.so-line{border:1px solid #c9d9e9;border-radius:8px;padding:18px;margin:18px 0;background:#f7faff}.so-line h3{margin-top:0}.so-hint{font-size:13px;line-height:1.6;background:#eaf2fd;padding:12px;border-radius:6px}.so-totals{display:flex;flex-wrap:wrap;gap:20px;padding:18px;background:#eaf2fd;border-left:4px solid #0a369d}.so-totals strong{font-size:20px}'''
JS = r'''
let salesOfferVersion=0,salesOfferCalculation=0;
function resetSalesOffers(){salesOfferVersion++;salesOfferCalculation++;$('sales-offer-form').reset();$('so-summary').replaceChildren();$('so-notice').textContent='';$('so-lines').replaceChildren();$('so-customer').replaceChildren();option($('so-customer'),'','Selecciona un cliente');(state.customers||[]).forEach(c=>option($('so-customer'),c.customer_id,c.legal_name||c.customer_id));addSalesOfferLine();renderSavedSalesOffers()}
function salesOfferField(parent,labelText,key,type='text'){const label=document.createElement('label');label.textContent=labelText;const input=document.createElement(type==='select'?'select':'input');if(type!=='select'){input.type='text';input.inputMode='decimal'}input.dataset.so=key;input.required=true;label.append(input);parent.append(label);return input}
function addSalesOfferLine(){if($('so-lines').children.length>=30)return;const row=document.createElement('section');row.className='so-line';const title=document.createElement('h3');title.textContent='ARTÍCULO';row.append(title);const fields=document.createElement('div');fields.className='fields';const article=salesOfferField(fields,'Artículo / SKU','article_id','select');option(article,'','Selecciona un artículo');state.articles.forEach(a=>option(article,a.article_id,a.article_id+' · '+(a.description||'')+' / '+a.unit_as_documented));salesOfferField(fields,'Cantidad','quantity');salesOfferField(fields,'Precio unitario antes de descuento (€)','unit_price');const discount=salesOfferField(fields,'Descuento de línea (%)','discount_value');discount.value='0';salesOfferField(fields,'IVA de línea (%)','vat_percent');row.append(fields);const hint=document.createElement('p');hint.className='so-hint';row.append(hint);const remove=document.createElement('button');remove.type='button';remove.textContent='Quitar artículo';remove.onclick=()=>{row.remove();salesOfferCalculation++;$('so-summary').replaceChildren()};row.append(remove);row.soRequest=0;row.querySelector('[data-so=article_id]').onchange=()=>loadSalesOrientation(row);$('so-lines').append(row);loadSalesOrientation(row)}
async function loadSalesOrientation(row){const seq=++row.soRequest,version=salesOfferVersion,dataset=$('dataset').value,article=row.querySelector('[data-so=article_id]').value,customer=$('so-customer').value,hint=row.querySelector('.so-hint');hint.textContent='Selecciona cliente y artículo para consultar referencias.';if(!article||!customer)return;try{const r=await api('/api/sales-proposals/context',{method:'POST',headers:{'Content-Type':'application/json','X-EIOS-Token':token},body:JSON.stringify({dataset_id:dataset,customer_id:customer,article_id:article})});if(!row.isConnected||seq!==row.soRequest||version!==salesOfferVersion||dataset!==$('dataset').value)return;const i=r.inventory;let text=i?'Stock de referencia: '+stockNumber(i.physical)+' físico · '+stockNumber(i.reserved)+' reservado · '+stockNumber(i.available)+' disponible / '+i.unit+' · '+stockDate(i.as_of_date)+' · '+i.material_nature:'Stock: sin datos comparables.';text+=' Últimas ventas comparables al cliente: '+(r.latest_sales.length?r.latest_sales.map(s=>stockDate(s.date)+' · '+stockNumber(s.quantity)+' '+s.unit+' · neto por unidad '+money(s.net_unit_price)+' EUR · '+s.invoice).join(' / '):'sin referencias.');text+=' Compra histórica de referencia: '+(r.reference_unit_cost===null?'sin referencia única comparable.':money(r.reference_unit_cost)+' EUR/unidad; excluye otros costes.');hint.textContent=text}catch(e){if(seq===row.soRequest&&version===salesOfferVersion)hint.textContent=e.message}}
function salesOfferData(){return {dataset_id:$('dataset').value,context_fingerprint:state.documentary_context.fingerprint,customer_id:$('so-customer').value,reference:$('so-reference').value.trim(),offer_date:inputDateISO($('so-date').value),valid_until:inputDateISO($('so-valid').value),delivery_date:inputDateISO($('so-delivery-date').value),due_date:inputDateISO($('so-due').value),delivery_location:$('so-delivery').value.trim(),payment_terms:$('so-payment').value.trim(),freight_net:parameterNumber($('so-freight').value),freight_vat_percent:parameterNumber($('so-freight-vat').value),lines:Array.from($('so-lines').children).map(row=>Object.fromEntries(Array.from(row.querySelectorAll('[data-so]')).map(input=>[input.dataset.so,input.dataset.so==='article_id'?input.value:parameterNumber(input.value)])))}}
async function submitSalesOffer(save){if(!$('sales-offer-form').reportValidity())return;const seq=++salesOfferCalculation,version=salesOfferVersion,dataset=$('dataset').value;const button=save?$('so-save'):$('so-preview');button.disabled=true;$('so-notice').textContent='';try{const payload=salesOfferData();const result=await api(save?'/api/sales-proposals':'/api/sales-proposals/preview',{method:'POST',headers:{'Content-Type':'application/json','X-EIOS-Token':token},body:JSON.stringify(payload)});if(version!==salesOfferVersion||dataset!==$('dataset').value)return;if(save){state.sales_proposals.unshift(result);renderSavedSalesOffers();$('so-notice').textContent='Oferta guardada con sus datos de referencia. No reserva stock ni registra una venta.'}if(seq!==salesOfferCalculation)return;const box=$('so-summary');box.replaceChildren();const totals=document.createElement('div');totals.className='so-totals';totals.textContent='Base '+money(result.net_amount)+' EUR · IVA '+money(result.vat_amount)+' EUR · TOTAL '+money(result.total)+' EUR';box.append(totals);(result.warnings||[]).forEach(w=>{const p=document.createElement('p');p.textContent=w;box.append(p)});result.lines.forEach(l=>{const p=document.createElement('p');p.textContent=l.article_id+' · Neto '+money(l.net_amount)+' EUR · Margen sobre compra histórica: '+(l.reference_margin_percent===null?'no calculable':money(l.reference_margin_percent)+' %')+'. Excluye portes y otros costes.';box.append(p)});}catch(e){if(version===salesOfferVersion)$('so-notice').textContent=e.message}finally{button.disabled=false}}
function renderSavedSalesOffers(){const box=$('so-saved');box.replaceChildren();(state.sales_proposals||[]).forEach(p=>{const row=document.createElement('tr');salesCells(row,[p.reference+' · '+stockDate(p.offer_date),p.customer.legal_name||p.customer.customer_id,money(p.total)+' EUR',stockDate(p.valid_until)]);const cell=document.createElement('td'),button=document.createElement('button');button.type='button';button.textContent='Documento para el cliente';button.onclick=async()=>{const dataset=$('dataset').value;button.disabled=true;try{const {html}=await api('/api/sales-proposals/report',{method:'POST',headers:{'Content-Type':'application/json','X-EIOS-Token':token},body:JSON.stringify({dataset_id:dataset,proposal_id:p.proposal_id})});if(dataset!==$('dataset').value)return;const blob=new Blob([html],{type:'text/html'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='Propuesta_venta_'+p.proposal_id+'.html';link.click();setTimeout(()=>URL.revokeObjectURL(url),60000)}catch(e){$('so-notice').textContent=e.message}finally{button.disabled=false}};cell.append(button);row.append(cell);box.append(row)});if(!box.children.length){const row=document.createElement('tr');salesCells(row,['Sin ofertas guardadas en esta versión.']);box.append(row)}}
$('so-add').onclick=addSalesOfferLine;$('so-customer').onchange=()=>{salesOfferCalculation++;$('so-summary').replaceChildren();Array.from($('so-lines').children).forEach(loadSalesOrientation)};$('so-preview').onclick=()=>submitSalesOffer(false);$('sales-offer-form').onsubmit=event=>{event.preventDefault();submitSalesOffer(true)};$('sales-offer-form').addEventListener('input',()=>{salesOfferCalculation++;$('so-summary').replaceChildren()});
'''
